const lead = $('Set Lead Configuration').item.json;

return {
  json: lead
};

const incoming = $('Set Lead Configuration').item.json;

const rows = $input.all();

const match = rows.find(item =>
  item.json["Source Record ID"] === incoming.source_record_id
);

return [
  {
    json: {
      duplicate_found: !!match,
      source_record_id: incoming.source_record_id,
      matched_row_number: match ? match.json.row_number : null
    }
  }
];

const body = $json.body ?? $json;

// Normalize common field variations
const senderName =
  body.name ??
  body.full_name ??
  body.contact_name ??
  '';

const senderEmail =
  body.email ??
  body.sender_email ??
  '';

const subject =
  body.subject ??
  body.title ??
  'Website Lead Enquiry';

const message =
  body.message ??
  body.enquiry ??
  body.details ??
  body.description ??
  '';

const company =
  body.company ??
  body.company_name ??
  '';


// Create a simple deterministic fingerprint if no submission ID exists
function simpleHash(str) {
  let hash = 5381;

  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash) + str.charCodeAt(i);
    hash = hash & 0xffffffff;
  }

  return Math.abs(hash).toString(16);
}

const suppliedId =
  body.submission_id ??
  body.id ??
  body.lead_id ??
  '';

const fingerprint = simpleHash(
  `${senderEmail}|${subject}|${message}`
);

const sourceRecordId = suppliedId
  ? `webhook:${suppliedId}`
  : `webhook:${fingerprint}`;


return {
  json: {
    source: 'webhook',

    source_record_id: sourceRecordId,

    sender_name: senderName,
    sender_email: senderEmail,

    recipient_email: '',

    subject: subject,
    message: message,

    received_at: new Date().toISOString(),

    company_hint: company,

    gmail_message_id: '',
    gmail_thread_id: '',
    internet_message_id: ''
  }
};

const lead = $json.output;

// Retrieve configuration + normalized email data
const config = $('Set Lead Configuration').item.json;

// Calculate individual score components
const scoreBreakdown = {
  clear_business_requirement:
    lead.clear_business_requirement === true
      ? config.pf_weight_clear_requirement
      : 0,

  business_customer:
    lead.business_customer === true
      ? config.pf_weight_business_customer
      : 0,

  purchase_intent:
    lead.intent === 'purchase'
      ? config.pf_weight_purchase_intent
      : 0,

  urgent_timeline:
    lead.urgent_timeline === true
      ? config.pf_weight_urgent_timeline
      : 0,

  budget:
    lead.budget_mentioned === true
      ? config.pf_weight_budget
      : 0,

  decision_maker:
    lead.decision_maker_indication === true
      ? config.pf_weight_decision_maker
      : 0,

  contact_details:
    lead.contact_details_present === true
      ? config.pf_weight_contact_details
      : 0
};

// Calculate total score
const score = Object.values(scoreBreakdown)
  .reduce((total, value) => total + value, 0);

// Calculate maximum possible score
const maxScore =
  config.pf_weight_clear_requirement +
  config.pf_weight_business_customer +
  config.pf_weight_purchase_intent +
  config.pf_weight_urgent_timeline +
  config.pf_weight_budget +
  config.pf_weight_decision_maker +
  config.pf_weight_contact_details;

// Determine classification from configurable thresholds
let classification;

if (score >= config.pf_hot_threshold) {
  classification = 'HOT';
} else if (score >= config.pf_warm_threshold) {
  classification = 'WARM';
} else {
  classification = 'LOW';
}

return {
  json: {
    ...config,
    ...lead,

    lead_id: `PF-${config.source_record_id.replace(/[^a-zA-Z0-9_-]/g, '-')}`,

    score_breakdown: scoreBreakdown,
    lead_score: score,
    max_possible_score: maxScore,
    classification: classification,

    status: 'NEW'
  }
};

const response = $json.output;

// Retrieve the original scored lead
const lead = $('Calculate Lead Score').item.json;

let finalBody = response.email_body.trim();

// Add configured business signature
if (
  lead.pf_business_signature &&
  lead.pf_business_signature.trim() !== ''
) {
  finalBody += '\n\n' + lead.pf_business_signature.trim();
}

return {
  json: {
    ...lead,
    draft_subject: response.email_subject,
    draft_body: finalBody,
    draft_status: 'AWAITING_APPROVAL'
  }
};
